<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/Core/PublicPage.php';
require dirname(__DIR__).'/app/Core/Database.php';
require dirname(__DIR__).'/app/Services/RegistrationService.php';
$error=null; $success=false;
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!Security::verifyCsrf($_POST['_csrf']??null)) { http_response_code(419); $error='Your form session expired. Refresh this page and try again.'; }
    else {
        try { $ip=(string)($_SERVER['REMOTE_ADDR']??'unknown'); if (filter_var($ip,FILTER_VALIDATE_IP)===false) $ip='unknown';
            RegistrationService::register(Database::connection(),$_POST,$ip); $success=true;
        } catch (InvalidArgumentException $e) { $error=$e->getMessage(); }
          catch (PDOException $e) { $error='We could not create this account. The username or email may already be registered, or the database is not ready.'; }
          catch (Throwable $e) { error_log('Registration failed: '.$e->getMessage()); $error='Registration is temporarily unavailable. Please check the portal configuration and try again later.'; }
    }
}
pageHeader('Create an Account','Register as a Resident or Visitor of Barangay San Antonio.');
?>
<main id="main-content"><section class="page-hero"><div class="page-hero-inner"><div class="breadcrumb"><a href="<?= Security::e(url()) ?>">Home</a> / Account Registration</div><p class="eyebrow">COMMUNITY PORTAL ACCOUNT</p><h1>Create an Account</h1><p>Register securely to access eligible Barangay San Antonio online services.</p></div></section><section class="section"><div class="content-layout"><article class="content-panel">
<?php if($success): ?><div class="notice info" role="status"><b>Registration received.</b><p>Your account was created as pending email verification. The local demo queues a verification message. Run the email outbox worker, then open the generated file in storage/mail-preview/ to use its verification link. You will not be signed in automatically.</p><p>For real email delivery, configure an approved SMTP provider before public deployment.</p></div><a class="action-primary" href="<?= Security::e(url('login.php')) ?>">Go to sign in</a>
<?php else: ?>
<?php if($error): ?><div class="form-error" role="alert"><?= Security::e($error) ?></div><?php endif; ?>
<form method="post" action="<?= Security::e(url('register.php')) ?>" class="portal-form">
<input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>">
<fieldset><legend>Account type</legend><label for="account_type">I am registering as <span aria-hidden="true">*</span></label><select id="account_type" name="account_type" required><option value="RESIDENT" <?= ($_POST['account_type']??'RESIDENT')==='RESIDENT'?'selected':'' ?>>Resident of Barangay San Antonio</option><option value="VISITOR" <?= ($_POST['account_type']??'')==='VISITOR'?'selected':'' ?>>Visitor</option></select></fieldset>
<fieldset><legend>Personal information</legend><div class="form-grid"><label>First name *<input name="first_name" maxlength="100" required value="<?= Security::e($_POST['first_name']??'') ?>" autocomplete="given-name"></label><label>Middle name <span class="optional">(optional)</span><input name="middle_name" maxlength="100" value="<?= Security::e($_POST['middle_name']??'') ?>" autocomplete="additional-name"></label><label>Last name *<input name="last_name" maxlength="100" required value="<?= Security::e($_POST['last_name']??'') ?>" autocomplete="family-name"></label><label>Suffix <span class="optional">(optional)</span><input name="suffix" maxlength="30" value="<?= Security::e($_POST['suffix']??'') ?>"></label></div></fieldset>
<fieldset><legend>Account credentials</legend><div class="form-grid"><label>Username *<input name="username" minlength="4" maxlength="30" pattern="[A-Za-z0-9][A-Za-z0-9._]{2,28}[A-Za-z0-9]" title="Use 4–30 letters, numbers, periods, or underscores; do not use consecutive punctuation." required autocomplete="username" value="<?= Security::e($_POST['username']??'') ?>"><small>4–30 characters; letters, numbers, periods, and underscores.</small></label><label>Email address *<input type="email" name="email" maxlength="254" required autocomplete="email" value="<?= Security::e($_POST['email']??'') ?>"></label><label>Password *<input type="password" name="password" minlength="12" maxlength="200" required autocomplete="new-password"><small>Use at least 12 characters.</small></label><label>Confirm password *<input type="password" name="confirm_password" minlength="12" maxlength="200" required autocomplete="new-password"></label></div></fieldset>
